type pageSearchHandlers struct{ *Server }

func (s pageSearchHandlers) GET(w http.ResponseWriter, r *http.Request) {
	sess, _, ok := s.ReadSession(w, r)
	if !ok {
		return
	}

	var query datapages.Query[dpapp.SearchParams]
	query.Values.Term = httpread.QueryValue(r.URL.RawQuery, "t")
	query.Values.Category = httpread.QueryValue(r.URL.RawQuery, "c")
	{
		if q := httpread.QueryValue(r.URL.RawQuery, "pmin"); q != "" {
			i, err := strconv.ParseInt(q, 10, 64)
			if err != nil {
				s.HTTPErrBad(w, "unexpected value for query parameter: pmin", err)
				return
			}
			query.Values.PriceMin = i
		}
	}
	{
		if q := httpread.QueryValue(r.URL.RawQuery, "pmax"); q != "" {
			i, err := strconv.ParseInt(q, 10, 64)
			if err != nil {
				s.HTTPErrBad(w, "unexpected value for query parameter: pmax", err)
				return
			}
			query.Values.PriceMax = i
		}
	}
	query.Values.Location = httpread.QueryValue(r.URL.RawQuery, "l")

	p := dpapp.PageSearch{
		App: s.app,
		Base: dpapp.Base{
			App: s.app,
		},
	}
	defer s.recoverPanic(w, r, nil, "PageSearch.GET")
	body, err := p.GET(r, sess, query)
	if err != nil {
		s.httpErrIntern(w, r, nil, "handling PageSearch.GET", err)
		return
	}
	genericHead := s.app.Head(r)

	bodyAttrs := func(w http.ResponseWriter) {
		httpserve.WriteReloadOnVisibility(w)

		_, _ = io.WriteString(w, ` data-signals:term="'`)
		htmlattr.WriteSignalString(w, query.Values.Term)
		_, _ = io.WriteString(w, `'"`)

		_, _ = io.WriteString(w, ` data-signals:category="'`)
		htmlattr.WriteSignalString(w, query.Values.Category)
		_, _ = io.WriteString(w, `'"`)

		_, _ = io.WriteString(w, ` data-signals:pmin="`)
		htmlattr.WriteSignalValue(w, strconv.FormatInt(query.Values.PriceMin, 10))
		_, _ = io.WriteString(w, `"`)

		_, _ = io.WriteString(w, ` data-signals:pmax="`)
		htmlattr.WriteSignalValue(w, strconv.FormatInt(query.Values.PriceMax, 10))
		_, _ = io.WriteString(w, `"`)

		_, _ = io.WriteString(w, ` data-signals:location="'`)
		htmlattr.WriteSignalString(w, query.Values.Location)
		_, _ = io.WriteString(w, `'"`)
	}

	bodySuffix := func(w http.ResponseWriter) {

		if sess.UserID() != "" {
			_, _ = io.WriteString(w, ` data-init="@get('/search/_$/')"`)
		}

		_, _ = io.WriteString(w, ` data-effect="const params = new URLSearchParams(location.search);
			if ($term) params.set('t', $term); else params.delete('t');
			if ($category) params.set('c', $category); else params.delete('c');
			if ($pmin) params.set('pmin', $pmin); else params.delete('pmin');
			if ($pmax) params.set('pmax', $pmax); else params.delete('pmax');
			if ($location) params.set('l', $location); else params.delete('l');
			const query = params.toString();
			window.history.replaceState(null, '', (query ? '/search?' + query : '/search') + location.hash);
		"`)
	}

	if err := s.writeHTML(
		w, r, sess, genericHead, nil, body, bodyAttrs, bodySuffix,
	); err != nil {
		s.LogErr("rendering PageSearch", err)
		return
	}
}

